#rf-root,.hf-root{--x3:#414b5a;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 6s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx.tx-iris-out{inset:auto;background:transparent;box-shadow:0 0 0 2400px var(--rf-surface);border-radius:50%;width:2400px;height:2400px;left:calc(50% - 1200px);top:calc(50% - 1200px);animation:tx-iris-out 0.5s cubic-bezier(.76,0,.24,1) 5.5s both;opacity:0}@keyframes tx-iris-out{from{opacity:1}to{opacity:1;width:0;height:0;left:50%;top:50%}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
